const lessons=[{"sentences":[{"speaker":"A","text":"Good morning I would like to renew my borrowed books because I am still reading them.","position":1,"audioStartSeconds":0,"audioEndSeconds":4.837458333333333},{"speaker":"B","text":"Good morning please let me check your library account on my computer screen right now.","position":2,"audioStartSeconds":5.037458333333333,"audioEndSeconds":10.197083333333333},{"speaker":"A","text":"Thank you my library card number is printed clearly on the back of the plastic.","position":3,"audioStartSeconds":10.397083333333333,"audioEndSeconds":15.436541666666667},{"speaker":"B","text":"I see your account and notice that two novels are already overdue by three days.","position":4,"audioStartSeconds":15.636541666666666,"audioEndSeconds":20.444041666666667},{"speaker":"A","text":"Oh I am sorry about that delay because I was quite busy studying for exams.","position":5,"audioStartSeconds":20.644041666666666,"audioEndSeconds":25.785791666666668},{"speaker":"B","text":"Do not worry since you can renew them online or right here at the desk.","position":6,"audioStartSeconds":25.985791666666668,"audioEndSeconds":30.496083333333335},{"speaker":"A","text":"Can I renew them for another two weeks even though another reader wants them?","position":7,"audioStartSeconds":30.696083333333334,"audioEndSeconds":35.064625},{"speaker":"B","text":"Unfortunately if another member places a reservation you cannot extend the borrowing period anymore.","position":8,"audioStartSeconds":35.264625,"audioEndSeconds":41.514625},{"speaker":"A","text":"Nobody has reserved these specific books yet so can I keep them longer today?","position":9,"audioStartSeconds":41.714625,"audioEndSeconds":46.444},{"speaker":"B","text":"Yes because there are no pending requests I can easily extend both items for you now.","position":10,"audioStartSeconds":46.644,"audioEndSeconds":52.06925},{"speaker":"A","text":"That is wonderful news and I will definitely finish reading them before next week arrives.","position":11,"audioStartSeconds":52.26925,"audioEndSeconds":57.926458333333336},{"speaker":"B","text":"Remember that if you forget next time you might receive a small daily fine charge.","position":12,"audioStartSeconds":58.12645833333333,"audioEndSeconds":63.139375},{"speaker":"A","text":"I understand completely and I will set a reminder on my smartphone calendar today.","position":13,"audioStartSeconds":63.339375,"audioEndSeconds":68.53270833333333},{"speaker":"B","text":"Is there anything else I can help you with regarding your membership privileges today?","position":14,"audioStartSeconds":68.73270833333333,"audioEndSeconds":73.59091666666667},{"speaker":"A","text":"No everything is perfectly clear now and I appreciate your friendly assistance this morning.","position":15,"audioStartSeconds":73.79091666666666,"audioEndSeconds":79.52129166666667},{"speaker":"B","text":"You are very welcome and have a wonderful time reading your interesting library books.","position":16,"audioStartSeconds":79.72129166666667,"audioEndSeconds":84.94804166666667}],"questions":[{"prompt":"What is the main purpose of the reader's visit?","options":["To pay a large fine.","To renew borrowed books.","To buy new novels."],"answer":"B","evidenceSentence":1,"evidence":"I would like to renew my borrowed books","explanation":"Người đọc đến thư viện với mục đích gia hạn sách đang mượn."},{"detail":true,"prompt":"What does the library employee check first?","options":["The reader's ID card.","The library account.","The smartphone calendar."],"answer":"B","evidenceSentence":2,"evidence":"check your library account on my computer screen","explanation":"Nhân viên thư viện kiểm tra tài khoản thư viện trên máy tính."},{"prompt":"Why were the novels overdue?","options":["The reader was studying for exams.","The computer system crashed.","The library was closed on Monday."],"answer":"A","evidenceSentence":5,"evidence":"I was quite busy studying for exams","explanation":"Sách bị quá hạn vì người đọc bận ôn thi."},{"prompt":"When are renewals not allowed according to the conversation?","options":["When another member places a reservation.","When the library closes for holidays.","When the books are too old."],"answer":"A","evidenceSentence":8,"evidence":"if another member places a reservation you cannot extend","explanation":"Không thể gia hạn nếu có thành viên khác đã đặt trước cuốn sách đó."},{"prompt":"What happens next regarding the current books?","options":["The employee extends both items.","The employee takes the books back.","The reader pays a fine immediately."],"answer":"A","evidenceSentence":10,"evidence":"I can easily extend both items for you now","explanation":"Nhân viên tiến hành gia hạn cả hai cuốn sách ngay tại quầy vì chưa ai đặt trước."},{"prompt":"What will the reader do next to avoid future problems?","options":["Buy a new smartphone.","Set a reminder on a calendar.","Return the books tomorrow."],"answer":"B","evidenceSentence":13,"evidence":"I will set a reminder on my smartphone calendar today","explanation":"Người đọc sẽ cài đặt nhắc nhở trên lịch điện thoại để tránh quên hạn trả sách."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
